(function(){"use strict";var P=window.FSP_MAATHAI_FIELD_1;if(!P){document.body.innerHTML="<p>Run npm run prototype:maathai-field.</p>";return}var S=P.scene,R=P.projection,selected=null,prov=false,level=3,svg=document.getElementById("field"),panel=document.getElementById("panel"),stage=document.getElementById("stage"),NS="http://www.w3.org/2000/svg";
function el(t,a,x){var n=document.createElementNS(NS,t);Object.entries(a||{}).forEach(e=>n.setAttribute(e[0],e[1]));if(x!=null)n.textContent=x;return n}function locus(id){return S.loci.find(x=>x.id===id)}function path(id){return S.paths.find(x=>x.id===id)}function proj(id){return R.pathProjection.find(x=>x.pathId===id)}function polar(r,t){return{x:r*Math.cos(t),y:r*Math.sin(t)}}function angle(id,d){var a=R.pathProjection.filter(x=>x.temporalDepth===d),i=a.findIndex(x=>x.pathId===id),sp=Math.PI*1.55,st=-Math.PI*.78;return a.length<=1?-.1:st+sp*(i/(a.length-1))}function ppoint(id){var p=proj(id),rg=R.timeRings.find(x=>x.depth===p.temporalDepth);return polar(rg.radius,angle(id,p.temporalDepth))}function sh(s,n){return s.length>n?s.slice(0,n-1)+"…":s}
function render(){svg.innerHTML="";var defs=el("defs"),mk=el("marker",{id:"arrow",markerWidth:"8",markerHeight:"8",refX:"6",refY:"3",orient:"auto"});mk.appendChild(el("path",{d:"M0,0 L0,6 L7,3 z",fill:"#6f7f96"}));defs.appendChild(mk);svg.appendChild(defs);var root=el("g",{id:"field-layer"});svg.appendChild(root);
R.timeRings.filter(x=>x.depth>0).forEach(r=>{root.appendChild(el("circle",{cx:0,cy:0,r:r.radius,class:"ring"}));root.appendChild(el("text",{x:8,y:-r.radius+16,class:"ring-label"},r.depth+" · "+r.label))});root.appendChild(el("circle",{cx:0,cy:0,r:468,class:"horizon"}));root.appendChild(el("text",{x:-210,y:-462,class:"ring-label"},R.horizonLabel));
S.paths.forEach(p=>{var pt=ppoint(p.id),ln=el("line",{x1:0,y1:0,x2:pt.x,y2:pt.y,class:"path-line "+(p.state==="CONDITIONAL"?"conditional ":"")+(selected===p.id?"selected":""),"data-prov":p.provenance[0]?.sourceClass||""});ln.onclick=()=>selectPath(p.id);root.appendChild(ln);var g=el("g",{class:"path-node"});g.appendChild(el("circle",{cx:pt.x,cy:pt.y,r:26}));g.appendChild(el("text",{x:pt.x,y:pt.y+42,"text-anchor":"middle"},sh(p.label,28)));g.onclick=()=>selectPath(p.id);root.appendChild(g)});
S.gates.forEach(g=>g.requiredByPathIds.forEach(pid=>{var pt=ppoint(pid),x=pt.x*.7,y=pt.y*.7,gg=el("g",{class:"gate"});gg.appendChild(el("polygon",{points:(x-16)+","+(y-13)+" "+(x+16)+","+(y-13)+" "+(x+16)+","+(y+13)+" "+(x-16)+","+(y+13)}));gg.appendChild(el("text",{x:x,y:y+4,"text-anchor":"middle"},"GATE"));gg.onclick=()=>selectGate(g.id,pid);root.appendChild(gg)}));
S.loci.filter(x=>x.id!=="FUTURE").forEach(l=>{var x=l.x*300,y=l.y*300,g=el("g",{class:"locus "+(l.id==="M"?"agent":"")});g.appendChild(el("circle",{cx:x,cy:y,r:l.id==="M"?38:27}));g.appendChild(el("text",{x:x,y:y+50,"text-anchor":"middle"},sh(l.label,30)));g.onclick=()=>selectLocus(l.id);root.appendChild(g)});
S.remainders.forEach((r,i)=>{var pt=polar(455,-2.4+i*.42),g=el("g",{class:"remainder"});g.appendChild(el("circle",{cx:pt.x,cy:pt.y,r:15}));g.appendChild(el("text",{x:pt.x,y:pt.y+29,"text-anchor":"middle"},"unknown"));g.onclick=()=>selectRemainder(r.id);root.appendChild(g)});
stage.className="stage scaffold-"+level+(prov?" prov-on":"");document.getElementById("return-overlay").style.display=level===0?"block":"none"}
function reqs(a){return a.map(r=>'<div class="req '+r.status+'"><strong>'+r.label+'</strong> · '+r.status+'<br><span class="small">'+r.explanation+'</span></div>').join("")}
function selectPath(id){selected=id;var p=path(id),q=proj(id),g=S.gates.find(x=>x.requiredByPathIds.includes(id));panel.innerHTML='<div class="title">'+p.label+'</div><p><span class="chip">'+p.family+'</span><span class="chip">'+p.state+'</span><span class="chip">distance '+q.temporalDepth+'</span></p><p>'+q.distanceMeaning+'</p><h3>What is already present / still needed?</h3>'+reqs(q.requirements)+(g?'<p class="notice"><strong>Gate:</strong> '+g.label+' · '+g.state+'</p>':'')+'<p class="small">Distance means how much must change first, not probability or recommendation.</p>';render()}
function selectGate(id,pid){selected=pid;var g=S.gates.find(x=>x.id===id),q=proj(pid);panel.innerHTML='<div class="title">'+g.label+'</div><p><span class="chip">'+g.state+'</span></p><p>What must become present before this path can open further?</p>'+reqs(q.requirements);render()}
function selectLocus(id){var l=locus(id);panel.innerHTML='<div class="title">'+l.label+'</div><p>'+l.roles.map(x=>'<span class="chip">'+x+'</span>').join("")+'</p><p class="small">'+(l.navigationalReconstruction?"Spatial placement is a navigational reconstruction.":"Bounded dossier locus.")+'</p>'}
function selectRemainder(id){var r=S.remainders.find(x=>x.id===id);panel.innerHTML='<div class="title">'+r.label+'</div><p><span class="chip">'+r.type+'</span></p><p>'+r.explanation+'</p><p class="small">This preserves what the scene does not know.</p>'}
document.querySelectorAll("[data-level]").forEach(b=>b.onclick=function(){level=Number(b.dataset.level);document.querySelectorAll("[data-level]").forEach(x=>x.classList.remove("active"));b.classList.add("active");render()});document.getElementById("prov").onclick=function(){prov=!prov;this.classList.toggle("active",prov);render()};document.getElementById("reset").onclick=function(){selected=null;panel.innerHTML='<div class="title">Select a path, gate, locus, or remainder marker</div><p class="small">The field is intentionally plural. No path is the historical answer.</p>';render()};render()})();